input.code:
const base = `
        homeowner = person "Homeowner" "Uses the platform to manage the household's energy use and costs."
        smartMeterProvider = softwareSystem "Smart Meter Provider" "Provides live meter readings. Operated by a different organization." "External"
        energyManager = softwareSystem "Energy Manager" "A home energy management platform that helps homeowners manage their household's energy use and costs." {
            dashboard = container "Dashboard" "A web app where homeowners see consumption and costs. Embeds the shared rates library, which computes energy prices from tariff and time of day." "Web App"
            schedulingService = container "Scheduling Service" "Plans charging and heating. Embeds the shared rates library, which computes energy prices from tariff and time of day." "Service"
            database = container "Database" "Stores meter readings and schedules." "Database"
        }
        homeowner -> dashboard "views consumption and costs" "Web browser"
        schedulingService -> smartMeterProvider "fetches live meter readings" "REST/JSON"
        schedulingService -> database "stores meter readings and schedules" "SQL"
`;

const probes = {
  scope: `workspace "W" "D" {
    scope "SoftwareSystem"
    model {
${base}
    }
}
`,
  views: `workspace "W" "D" {
    model {
${base}
    }
    views {
        systemContext energyManager "SystemContext" "System context diagram for the Energy Manager." {
            include *
            autoLayout
        }
        container energyManager "Containers" "Container diagram for the Energy Manager." {
            include *
            autoLayout
        }
    }
}
`,
  docsBlock: `workspace "W" "D" {
    model {
        smartMeterProvider = softwareSystem "Smart Meter Provider" "Provides live meter readings. Operated by a different organization." "External"
        energyManager = softwareSystem "Energy Manager" "A home energy management platform." {
            dashboard = container "Dashboard" "A web app." "Web App"
            docs {
                "Overview" "The Energy Manager platform."
            }
        }
    }
}
`,
  decisionsBlock: `workspace "W" "D" {
    model {
        smartMeterProvider = softwareSystem "Smart Meter Provider" "Provides live meter readings. Operated by a different organization." "External"
        energyManager = softwareSystem "Energy Manager" "A home energy management platform." {
            dashboard = container "Dashboard" "A web app." "Web App"
            decisions {
                "Use a shared rates library" "Both application parts embed the shared rates library so pricing logic stays consistent."
            }
        }
    }
}
`
};

const out = {};
for (const [name, dsl] of Object.entries(probes)) {
  const r = await tools.structurizr.parse({ dsl });
  out[name] = r;
}
return out;

